const jwt = require('jsonwebtoken');

function autenticar(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  try {
    req.usuario = jwt.verify(token, process.env.JWT_SECRETO, {
      algorithms: ['HS256'],
    });
    next();
  } catch {
    res.sendStatus(401); // firma inválida o token expirado
  }
}

test('aplica 10% de descuento a pedidos de más de 100', async () => {
  const repo = { obtenerProducto: jest.fn().mockResolvedValue({ precio: 60 }) };
  const servicio = new PedidoService(repo);

  const total = await servicio.calcularTotal({ productoId: 42, cantidad: 2 });

  expect(total).toBe(108);
  expect(repo.obtenerProducto).toHaveBeenCalledWith(42);
});

